function changeDepth()
{
   if(false == newDepth)
   {
      return false;
   }
   var _loc3_;
   var _loc2_;
   _loc3_ = this.allUnit.length - 1;
   while(_loc3_ >= 1)
   {
      _loc2_ = this.allUnit.length - 1;
      while(_loc2_ >= 0)
      {
         if(_loc3_ != _loc2_)
         {
            if(this.allUnit[_loc3_]._y < this.allUnit[_loc2_]._y && this.allUnit[_loc3_].getDepth() > this.allUnit[_loc2_].getDepth() || this.allUnit[_loc3_]._y > this.allUnit[_loc2_]._y && this.allUnit[_loc3_].getDepth() < this.allUnit[_loc2_].getDepth())
            {
               if(this.allUnit[_loc3_]._visible && this.allUnit[_loc2_]._visible)
               {
                  this.allUnit[_loc3_].swapDepths(this.allUnit[_loc2_]);
               }
            }
         }
         _loc2_ = _loc2_ - 1;
      }
      _loc3_ = _loc3_ - 1;
   }
   return true;
}
