   i = bossLevels.length;
   while(i > 0)
   {
      if(bossLevels[i - 1].name == tName)
      {
         _loc1_ = i - 1;
         break;
      }
      i--;
   }
   if(_loc1_ < 0)
   {
      return false;
   }
   if(bossLevels[_loc1_].levels == 1)
   {
      bossLevels[_loc1_].levels = 5;
   }
   else if(bossLevels[_loc1_].levels < bossLevels[_loc1_].maxLevels)
   {
      bossLevels[_loc1_].levels += 5;
   }
   else if(bossLevels[_loc1_].moreFire < 2 * bossLevels[_loc1_].maxLevels)
   {
      bossLevels[_loc1_].moreFire += 5;
   }
};
