this.initMonster = function(beginNum, endNum, monster)
{
   var _loc2_;
   var _loc4_;
   _loc2_ = beginNum;
   _loc4_ = 1;
   while(_loc2_ <= endNum && _loc2_ < 7)
   {
      this["monster" + _loc2_].type = monster.type;
      this["monster" + _loc2_].attackTypeNum = monster.attackTypeNum;
      this["monster" + _loc2_].attackType = monster.attackType;
      this["monster" + _loc2_].myName = monster.myName;
      this["monster" + _loc2_]._x = monster.xy["x" + _loc4_];
      this["monster" + _loc2_]._y = monster.xy["y" + _loc4_];
      this["monster" + _loc2_].monsterName.textColor = monster.tColor;
      this["monster" + _loc2_].monsterName.text = monster.levels + "级" + monster.myName;
      this["monster" + _loc2_].levels = monster.levels;
      this["monster" + _loc2_].minAttack = monster.attack * (monster.levels + monster.baseLevels) * 0.8;
      this["monster" + _loc2_].maxAttack = monster.attack * (monster.levels + monster.baseLevels) * 1.2;
      this["monster" + _loc2_].defense = monster.defense * (monster.levels + monster.baseLevels);
      this["monster" + _loc2_].maxLife = monster.life * (monster.levels + monster.baseLevels);
      this["monster" + _loc2_].life = this["monster" + _loc2_].maxLife;
      this["monster" + _loc2_].attackFire = Math.floor(monster.attackFire + monster.levels * 2);
      if(this["monster" + _loc2_].attackFire <= role.attackFire - 5)
      {
         this["monster" + _loc2_].monsterFire.textColor = 65280;
         this["monster" + _loc2_].monsterFire.text = "战斗力 " + this["monster" + _loc2_].attackFire;
      }
      else if(this["monster" + _loc2_].attackFire >= role.attackFire + 5)
      {
         this["monster" + _loc2_].monsterFire.textColor = 16724787;
         this["monster" + _loc2_].monsterFire.text = "战斗力 " + this["monster" + _loc2_].attackFire;
      }
      else
      {
         this["monster" + _loc2_].monsterFire.textColor = 16777215;
         this["monster" + _loc2_].monsterFire.text = "战斗力 " + this["monster" + _loc2_].attackFire;
      }
      this["monster" + _loc2_].burst = monster.burst;
      this["monster" + _loc2_].jook = monster.jook;
      this["monster" + _loc2_].reduceDamage = monster.reduceDamage;
      this["monster" + _loc2_].wind = monster.wind;
      this["monster" + _loc2_].fire = monster.fire;
      this["monster" + _loc2_].soil = monster.soil;
      this["monster" + _loc2_].water = monster.water;
      this["monster" + _loc2_].stopTime = monster.stopTime;
      this["monster" + _loc2_].guardLength = monster.guardLength;
      this["monster" + _loc2_].guardHeight = monster.guardHeight;
      this["monster" + _loc2_].attackLength = monster.attackLength + (random(20) - 10);
      this["monster" + _loc2_].attackHeight = monster.attackHeight + (random(10) - 5);
