      return false;
   }
   var _loc5_ = 300;
   if(level > _loc5_)
   {
      level = _loc5_;
   }
   var _loc4_ = random(_root.devilSoul.length - 1) + 1;
   var _loc3_ = (_root.maxSoul[_loc4_] - _root.minSoul[_loc4_]) * level / _loc5_;
