               this.stone2.setThing({type:"空格"});
               return true;
            }
            if(this.stone1.val1 < 15 && _root.map.role.xxx_credit >= this.stone1.val1 - 6)
            {
               _root.map.role.xxx_credit -= this.stone1.val1 - 6;
               _global.sysMsg.addMsg("声望 -" + (this.stone1.val1 - 6));
               this.stone1.setThing({type:"宝石",name:"高级战斗力宝石",val1:this.stone1.val1 + 1,salePrice:2000});
